function setup() {
  // pixelDensity(5);
  createCanvas(windowWidth,windowHeight);
  background(0);
}

function draw() {
  push();
  fill(0);
  rect(0, 0, width, height);
  translate(width / 2, height / 2);
  let totalScale = 1.25;
  divAng(0, max(width, height) * totalScale, 0, PI * 2, 12, colors1); //main functionを使う
  pop();
  noLoop();
}

//functionを作る
function divAng(stR, edR, stAng, edAng, d, colors) {　    
  //　color：設定してグループからランダムに抽出して使う
  if (random(1) < 0.2) {
    colors = colors1;
  } else  {
    colors = colors2;
  }

  push();

  rotate(random(-PI, PI));
  let ww = pow(edR - stR, 1.3 - d / 4) * random(0.1,0.5);
  let cc = color(random(colors));
  stroke(cc);
  strokeWeight(ww);
  strokeCap(SQUARE);
  let rr = edR;
  noFill();
  arc(0, 0, stR, stR, stAng, edAng);

  let ratio = random(0.3, 0.7);
  if (d > 0) {
    if (random(0,1) < 0.45) {
      let splitNum = int(random(1,4));
      for (let i = 1; i <= splitNum; i++) {
        divAng(
          stR,
          edR,
          stAng + ((i - 1) * (edAng - stAng)) / splitNum,
          stAng + (i * (edAng - stAng)) / splitNum,
          d - 1
        );
      }
    } else {
      divAng(stR, stR + ratio * (edR - stR), stAng, edAng, d - 1);
      divAng(stR + ratio * (edR - stR), edR, stAng, edAng, d - 1);
    }
  }
  pop();
}

function mouseClicked(){
	loop();
}

function keyTyped() {
  if (key === "s" || key === "S") {
    noLoop();
    saveCanvas("DotandDashLine-004", "png");
  }
}

